comments.body:
I noticed that if I wrap the function with another jit, then AOT works for the wrapper:

```
@jax.jit
def f5_host_wrapper(x):
  return f5_host(x)

out_f5_wrapper = f5_wrapper(operand)
print(f"{out_f5_wrapper=}\n")  # Must have added 1 (runs on CPU)
assert np.allclose(out_f5_wrapper, 1.)

print("f5_wrapper=", f5_wrapper.lower(operand).compiler_ir())

out_f5_wrapper_aot = f5_wrapper.lower(operand).compile()(operand)
print(f"{out_f5_wrapper_aot=}\n")  # Must have added 1 (runs on CPU), but actually added 2
assert np.allclose(out_f5_wrapper_aot, 1.)
```

The output of the above is:
```
out_f5_wrapper=Array(1., dtype=float32)

f5_wrapper= module @jit_f5_wrapper attributes {mhlo.num_partitions = 1 : i32, mhlo.num_replicas = 1 : i32} {
  func.func public @main(%arg0: tensor<f32>) -> (tensor<f32> {jax.result_info = "result"}) {
    %0 = call @f5_host(%arg0) {mhlo.frontend_attributes = {_xla_compute_type = "host"}} : (tensor<f32>) -> tensor<f32>
    return %0 : tensor<f32>
  }
  func.func private @f5_host(%arg0: tensor<f32>) -> tensor<f32> {
    %c = stablehlo.constant {mhlo.frontend_attributes = {_xla_compute_type = "host"}} dense<0> : tensor<i32>
    %c_0 = stablehlo.constant dense<0> : tensor<i32>
    %c_1 = stablehlo.constant dense<1> : tensor<i32>
    %0 = stablehlo.clamp %c_0, %c, %c_1 {mhlo.frontend_attributes = {_xla_compute_type = "host"}} : tensor<i32>
    %1 = "stablehlo.case"(%0) ({
      %cst = stablehlo.constant dense<1.000000e+00> : tensor<f32>
      %2 = stablehlo.add %arg0, %cst {mhlo.frontend_attributes = {_xla_compute_type = "host"}} : tensor<f32>
      stablehlo.return %2 : tensor<f32>
    }, {
      %cst = stablehlo.constant dense<2.000000e+00> : tensor<f32>
      %2 = stablehlo.add %arg0, %cst {mhlo.frontend_attributes = {_xla_compute_type = "host"}} : tensor<f32>
      stablehlo.return %2 : tensor<f32>
    }) {mhlo.frontend_attributes = {_xla_compute_type = "host"}} : (tensor<i32>) -> tensor<f32>
    return %1 : tensor<f32>
  }
}

out_f5_wrapper_aot=Array(1., dtype=float32)

```

Note also that the lowering now contains the `_xla_compute_host = "host"` attribute but before it did not.

